import { createClient } from '@supabase/supabase-js';
import { Project, Student, Teacher, ProjectTeacher, Format, TeacherRole, Status, Program, User } from '../types';

const supabaseUrl = process.env.SUPABASE_URL || '';
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || '';

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

const generateId = (): string => Date.now().toString(36) + Math.random().toString(36).substring(2);

// Mapeo de campos CamelCase a snake_case para Supabase si es necesario, 
// o simplemente asegurar que las tablas coincidan.
// Para este ejemplo, asumiremos que las tablas usan los nombres de las interfaces.

export const db = {
    // Auth & Users
    getUsers: async () => {
        const { data } = await supabase.from('users').select('*');
        return data || [];
    },
    getUserByUsername: async (username: string) => {
        const { data } = await supabase.from('users').select('*').ilike('username', username).single();
        return data;
    },
    deleteUser: async (id: string) => {
        await supabase.from('users').delete().eq('id', id);
    },

    // Projects
    getProjects: async () => {
        const { data } = await supabase.from('projects').select('*');
        return data || [];
    },
    getProjectById: async (id: string) => {
        const { data } = await supabase.from('projects').select('*').eq('id', id).single();
        return data;
    },
    addProject: async (project: Omit<Project, 'id'>) => {
        const id = generateId();
        const { data } = await supabase.from('projects').insert([{ ...project, id }]).select().single();
        return data;
    },
    updateProject: async (project: Project) => {
        const { data } = await supabase.from('projects').update(project).eq('id', project.id).select().single();
        return data;
    },
    deleteProject: async (id: string) => {
        // La lógica de cascada se recomienda manejarla en Supabase (ON DELETE SET NULL/CASCADE)
        await supabase.from('projects').delete().eq('id', id);
    },

    // Students
    getStudents: async () => {
        const { data } = await supabase.from('students').select('*');
        return data || [];
    },
    getStudentById: async (id: string) => {
        const { data } = await supabase.from('students').select('*').eq('id', id).single();
        return data;
    },
    addStudent: async (student: Omit<Student, 'id'>) => {
        const id = generateId();
        const { data: newStudent } = await supabase.from('students').insert([{ ...student, id }]).select().single();

        // Crear usuario automático
        const userId = generateId();
        await supabase.from('users').insert([{
            id: userId,
            username: student.email.split('@')[0],
            password: student.cedula,
            role: 'student',
            studentId: id
        }]);

        return newStudent;
    },
    updateStudent: async (student: Student) => {
        const { data } = await supabase.from('students').update(student).eq('id', student.id).select().single();
        // Actualizar usuario asociado
        await supabase.from('users').update({
            username: student.email.split('@')[0],
            password: student.cedula
        }).eq('studentId', student.id);
        return data;
    },
    deleteStudent: async (id: string) => {
        await supabase.from('users').delete().eq('studentId', id);
        await supabase.from('students').delete().eq('id', id);
    },

    // Teachers
    getTeachers: async () => {
        const { data } = await supabase.from('teachers').select('*');
        return data || [];
    },
    getTeacherById: async (id: string) => {
        const { data } = await supabase.from('teachers').select('*').eq('id', id).single();
        return data;
    },
    addTeacher: async (teacher: Omit<Teacher, 'id'>) => {
        const id = generateId();
        const { data: newTeacher } = await supabase.from('teachers').insert([{ ...teacher, id }]).select().single();

        // Crear usuario automático
        const userId = generateId();
        await supabase.from('users').insert([{
            id: userId,
            username: teacher.email.split('@')[0],
            password: teacher.cedula,
            role: 'teacher',
            teacherId: id
        }]);

        return newTeacher;
    },
    updateTeacher: async (teacher: Teacher) => {
        const { data } = await supabase.from('teachers').update(teacher).eq('id', teacher.id).select().single();
        await supabase.from('users').update({
            username: teacher.email.split('@')[0],
            password: teacher.cedula
        }).eq('teacherId', teacher.id);
        return data;
    },
    deleteTeacher: async (id: string) => {
        await supabase.from('users').delete().eq('teacherId', id);
        await supabase.from('teachers').delete().eq('id', id);
    },

    // Project Teachers (Union Table)
    getProjectTeachers: async () => {
        const { data } = await supabase.from('project_teachers').select('*');
        return data || [];
    },
    addProjectTeacher: async (pt: Omit<ProjectTeacher, 'id'>) => {
        const id = generateId();
        const { data } = await supabase.from('project_teachers').insert([{ ...pt, id }]).select().single();
        return data;
    },
    deleteProjectTeacher: async (id: string) => {
        await supabase.from('project_teachers').delete().eq('id', id);
    },
    deleteProjectTeachersByProject: async (projectId: string) => {
        await supabase.from('project_teachers').delete().eq('project_id', projectId);
    },

    // catalogs
    getPrograms: async () => (await supabase.from('programs').select('*')).data || [],
    getStatuses: async () => (await supabase.from('statuses').select('*')).data || [],
    getFormats: async () => (await supabase.from('formats').select('*')).data || [],
    getTeacherRoles: async () => (await supabase.from('teacher_roles').select('*')).data || [],

    addProgram: async (p: Omit<Program, 'id'>) => (await supabase.from('programs').insert([{...p, id: generateId()}]).select().single()).data,
    updateProgram: async (p: Program) => (await supabase.from('programs').update(p).eq('id', p.id).select().single()).data,
    deleteProgram: async (id: string) => await supabase.from('programs').delete().eq('id', id),

    addStatus: async (p: Omit<Status, 'id'>) => (await supabase.from('statuses').insert([{...p, id: generateId()}]).select().single()).data,
    updateStatus: async (p: Status) => (await supabase.from('statuses').update(p).eq('id', p.id).select().single()).data,
    deleteStatus: async (id: string) => await supabase.from('statuses').delete().eq('id', id),

    addFormat: async (p: Omit<Format, 'id'>) => (await supabase.from('formats').insert([{...p, id: generateId()}]).select().single()).data,
    updateFormat: async (p: Format) => (await supabase.from('formats').update(p).eq('id', p.id).select().single()).data,
    deleteFormat: async (id: string) => await supabase.from('formats').delete().eq('id', id),

    addTeacherRole: async (p: Omit<TeacherRole, 'id'>) => (await supabase.from('teacher_roles').insert([{...p, id: generateId()}]).select().single()).data,
    updateTeacherRole: async (p: TeacherRole) => (await supabase.from('teacher_roles').update(p).eq('id', p.id).select().single()).data,
    deleteTeacherRole: async (id: string) => await supabase.from('teacher_roles').delete().eq('id', id),

    // Helpers
    initializeDB: () => { /* No-op con Supabase real */ }
};

import React, { createContext, useState, useContext, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { User } from '../types';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isAdmin: boolean;
  isTeacher: boolean;
  isStudent: boolean;
  canEditProject: (projectId: string) => Promise<boolean>;
  canGradeProject: (projectId: string) => Promise<{ canGrade: boolean, reviewerRole: string | null }>;
  login: (username: string, password: string) => Promise<boolean>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    const storedUser = localStorage.getItem('degreeProjectManagerUser');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  }, []);

  const login = async (username: string, password: string): Promise<boolean> => {
    const foundUser = await db.getUserByUsername(username);
    if (foundUser && foundUser.password === password) {
      setUser(foundUser);
      localStorage.setItem('degreeProjectManagerUser', JSON.stringify(foundUser));
      return true;
    }
    return false;
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('degreeProjectManagerUser');
  };

  const getProjectRolesForCurrentUser = async (projectId: string): Promise<string[]> => {
    if (!user || !user.teacherId) return [];
    const projectTeachers = await db.getProjectTeachers();
    const roles = await db.getTeacherRoles();
    const userAssignments = projectTeachers.filter(
      pt => pt.projectId === projectId && pt.teacherId === user.teacherId
    );
    return userAssignments.map(assignment => {
      return roles.find(r => r.id === assignment.roleId)?.name || '';
    }).filter(Boolean);
  };

  const canEditProject = async (projectId: string): Promise<boolean> => {
    if (!user) return false;
    if (user.role === 'admin') return true;
    if (user.role !== 'teacher') return false;
    const userRoles = await getProjectRolesForCurrentUser(projectId);
    return userRoles.some(role => role.toLowerCase().includes('director'));
  };

  const canGradeProject = async (projectId: string): Promise<{ canGrade: boolean, reviewerRole: string | null }> => {
      if (!user) return { canGrade: false, reviewerRole: null };
      if (user.role === 'admin') return { canGrade: true, reviewerRole: 'admin' };
      if (user.role !== 'teacher') return { canGrade: false, reviewerRole: null };

      const userRoles = await getProjectRolesForCurrentUser(projectId);
      const reviewerRole = userRoles.find(role => role.toLowerCase().includes('evaluador'));

      return {
          canGrade: !!reviewerRole,
          reviewerRole: reviewerRole || null
      };
  };

  const isAuthenticated = !!user;
  const isAdmin = user?.role === 'admin';
  const isTeacher = user?.role === 'teacher';
  const isStudent = user?.role === 'student';

  return (
    <AuthContext.Provider value={{ user, isAuthenticated, isAdmin, isTeacher, isStudent, login, logout, canEditProject, canGradeProject }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { useEffect, useState } from 'react';
import { db } from '../services/database';
import { Project, Status } from '../types';
import { ProjectIcon, StudentIcon, TeacherIcon } from '../components/Icons';

interface StatCardProps {
    icon: React.ReactNode;
    title: string;
    value: number;
    color: string;
}

const StatCard: React.FC<StatCardProps> = ({ icon, title, value, color }) => (
    <div className="bg-white rounded-lg shadow p-6 flex items-center">
        <div className={`p-3 rounded-full mr-4 ${color}`}>
            {icon}
        </div>
        <div>
            <p className="text-sm text-gray-500">{title}</p>
            <p className="text-2xl font-bold text-gray-800">{value}</p>
        </div>
    </div>
);

export const DashboardPage: React.FC = () => {
    const [stats, setStats] = useState({
        projects: 0,
        students: 0,
        teachers: 0,
        unassignedStudents: 0
    });
    const [recentProjects, setRecentProjects] = useState<Project[]>([]);
    const [statuses, setStatuses] = useState<Status[]>([]);

    useEffect(() => {
        const loadData = async () => {
            const [projects, students, teachers, allStatuses] = await Promise.all([
                db.getProjects(),
                db.getStudents(),
                db.getTeachers(),
                db.getStatuses()
            ]);

            setStatuses(allStatuses);
            setStats({
                projects: projects.length,
                students: students.length,
                teachers: teachers.length,
                unassignedStudents: students.filter(s => !s.projectId).length
            });

            setRecentProjects(
                [...projects]
                    .sort((a, b) => new Date(b.presentationDate).getTime() - new Date(a.presentationDate).getTime())
                    .slice(0, 5)
            );
        };
        loadData();
    }, []);

    const getStatusName = (id: string) => statuses.find(s => s.id === id)?.name || 'Desconocido';

    return (
        <div className="space-y-6">
            <h1 className="text-3xl font-bold text-gray-800">Panel Principal</h1>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard 
                    icon={<ProjectIcon className="h-6 w-6 text-white" />} 
                    title="Proyectos Totales" 
                    value={stats.projects}
                    color="bg-blue-500"
                />
                <StatCard 
                    icon={<StudentIcon className="h-6 w-6 text-white" />} 
                    title="Estudiantes Totales" 
                    value={stats.students}
                    color="bg-green-500"
                />
                <StatCard 
                    icon={<TeacherIcon className="h-6 w-6 text-white" />} 
                    title="Docentes Totales" 
                    value={stats.teachers}
                    color="bg-purple-500"
                />
                 <StatCard 
                    icon={<StudentIcon className="h-6 w-6 text-white" />} 
                    title="Estudiantes sin Asignar" 
                    value={stats.unassignedStudents}
                    color="bg-yellow-500"
                />
            </div>

            <div className="bg-white rounded-lg shadow">
                <h2 className="text-xl font-semibold text-gray-700 p-6 border-b">Proyectos Recientes</h2>
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">Título</th>
                                <th className="px-6 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">Fecha de Presentación</th>
                                <th className="px-6 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">Estado</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200">
                            {recentProjects.map(project => (
                                <tr key={project.id}>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{project.title}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{project.presentationDate}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">
                                        <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-blue-100 text-blue-800">
                                            {getStatusName(project.statusId)}
                                        </span>
                                    </td>
                                </tr>
                            ))}
                             {recentProjects.length === 0 && (
                                <tr>
                                    <td colSpan={3} className="text-center py-10 text-gray-500">No se encontraron proyectos recientes.</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { Project, Student, Teacher, TeacherRole, Status, Format, ProjectTeacher } from '../types';
import { Modal } from '../components/Modal';
import { ConfirmationDialog } from '../components/ConfirmationDialog';
import { PlusIcon, EditIcon, TrashIcon } from '../components/Icons';
import { useAuth } from '../contexts/AuthContext';

const ProjectForm: React.FC<{
    project: Partial<Project> | null;
    onSave: (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>) => void;
    onClose: () => void;
    statuses: Status[];
    formats: Format[];
    teachers: Teacher[];
    roles: TeacherRole[];
    initialAssignments: ProjectTeacher[];
    canEditDetails: boolean;
    gradeInfo: { canGrade: boolean, reviewerRole: string | null };
}> = ({ project, onSave, onClose, statuses, formats, teachers, roles, initialAssignments, canEditDetails, gradeInfo }) => {
    const { isAdmin } = useAuth();
    const [formData, setFormData] = useState<Partial<Project>>({});
    const [assignments, setAssignments] = useState<Array<{teacherId: string, roleId: string, tempId: number}>>([]);
    const [newAssignment, setNewAssignment] = useState({ teacherId: '', roleId: '' });
    const [projectFormatName, setProjectFormatName] = useState('');

    useEffect(() => {
        const initialData: Partial<Project> = {
            title: '', presentationDate: '', filesUrl: '',
            statusId: statuses[0]?.id || '', formatId: formats[0]?.id || '',
            isApprovedByDirector: false, writtenGradeReviewer1: null,
            presentationGradeReviewer1: null, writtenGradeReviewer2: null,
            presentationGradeReviewer2: null, ...project
        };
        setFormData(initialData);

        if (initialData.formatId) {
            const format = formats.find(f => f.id === initialData.formatId);
            setProjectFormatName(format?.name || '');
        } else {
            setProjectFormatName('');
        }

        setAssignments(initialAssignments.map(a => ({ teacherId: a.teacherId, roleId: a.roleId, tempId: Math.random() })));
        setNewAssignment({ teacherId: '', roleId: '' });
    }, [project, initialAssignments, statuses, formats]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        if (type === 'number') {
            setFormData(prev => ({ ...prev, [name]: value === '' ? null : parseFloat(value) }));
        } else {
            setFormData(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleCheckboxChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, checked } = e.target;
        setFormData(prev => ({ ...prev, [name]: checked }));
    };

    const handleGradeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        const grade = value === '' ? null : Math.max(0, Math.min(5, parseFloat(value)));
        if (gradeInfo.reviewerRole?.includes('1')) {
            setFormData(prev => ({ ...prev, [name === 'writtenGrade' ? 'writtenGradeReviewer1' : 'presentationGradeReviewer1']: grade }));
        } else if (gradeInfo.reviewerRole?.includes('2')) {
            setFormData(prev => ({ ...prev, [name === 'writtenGrade' ? 'writtenGradeReviewer2' : 'presentationGradeReviewer2']: grade }));
        } else if (gradeInfo.reviewerRole === 'admin') {
            if(formData.writtenGradeReviewer1 === null && formData.presentationGradeReviewer1 === null) {
                 setFormData(prev => ({ ...prev, [name === 'writtenGrade' ? 'writtenGradeReviewer1' : 'presentationGradeReviewer1']: grade }));
            } else {
                 setFormData(prev => ({ ...prev, [name === 'writtenGrade' ? 'writtenGradeReviewer2' : 'presentationGradeReviewer2']: grade }));
            }
        }
    };

    const handleAssignmentChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        setNewAssignment(prev => ({...prev, [e.target.name]: e.target.value}));
    };

    const handleAddAssignment = () => {
        if (newAssignment.teacherId && newAssignment.roleId) {
            if (assignments.some(a => a.teacherId === newAssignment.teacherId)) {
                alert('Este docente ya ha sido asignado al proyecto.'); return;
            }
            setAssignments(prev => [...prev, {...newAssignment, tempId: Math.random()}]);
            setNewAssignment({ teacherId: '', roleId: '' });
        } else {
            alert('Por favor, selecciona un docente y un rol.');
        }
    };

    const handleRemoveAssignment = (tempId: number) => {
        setAssignments(prev => prev.filter(a => a.tempId !== tempId));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave(formData, assignments);
    };

    const getTeacherName = (id: string) => teachers.find(t => t.id === id)?.name || 'Desconocido';
    const getRoleName = (id: string) => roles.find(r => r.id === id)?.name || 'Desconocido';

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-4">
                <div><label className="block text-sm font-medium text-gray-700">Título</label><input type="text" name="title" value={formData.title || ''} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 disabled:bg-gray-100" disabled={!canEditDetails} /></div>
                <div><label className="block text-sm font-medium text-gray-700">Fecha</label><input type="date" name="presentationDate" value={formData.presentationDate || ''} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 disabled:bg-gray-100" disabled={!canEditDetails}/></div>
                <div><label className="block text-sm font-medium text-gray-700">Estado</label><select name="statusId" value={formData.statusId || ''} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 disabled:bg-gray-100" disabled={!canEditDetails && !gradeInfo.canGrade}>{statuses.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></div>
            </div>

            {canEditDetails && (
                <div className="space-y-4 pt-4 border-t">
                    <h4 className="text-lg font-medium">Asignaciones</h4>
                    <div className="space-y-2">{assignments.map(a => (<div key={a.tempId} className="flex justify-between bg-gray-50 p-2 rounded"><span>{getTeacherName(a.teacherId)} - {getRoleName(a.roleId)}</span><button type="button" onClick={() => handleRemoveAssignment(a.tempId)} className="text-red-500"><TrashIcon className="h-4 w-4"/></button></div>))}</div>
                    <div className="flex gap-2"><select name="teacherId" value={newAssignment.teacherId} onChange={handleAssignmentChange} className="border p-2 rounded flex-grow"><option value="">Docente...</option>{teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select><select name="roleId" value={newAssignment.roleId} onChange={handleAssignmentChange} className="border p-2 rounded flex-grow"><option value="">Rol...</option>{roles.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}</select><button type="button" onClick={handleAddAssignment} className="bg-primary-500 text-white px-3 rounded">Añadir</button></div>
                </div>
            )}

            <div className="flex justify-end gap-2 pt-6 border-t">
                <button type="button" onClick={onClose} className="px-4 py-2 border rounded">Cancelar</button>
                <button type="submit" className="px-4 py-2 bg-primary-600 text-white rounded">Guardar</button>
            </div>
        </form>
    );
};

export const ProjectsPage: React.FC = () => {
    const { isAdmin, canEditProject, canGradeProject } = useAuth();
    const [projects, setProjects] = useState<Project[]>([]);
    const [students, setStudents] = useState<Student[]>([]);
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [roles, setRoles] = useState<TeacherRole[]>([]);
    const [statuses, setStatuses] = useState<Status[]>([]);
    const [formats, setFormats] = useState<Format[]>([]);
    const [projectTeachers, setProjectTeachers] = useState<ProjectTeacher[]>([]);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);

    const [userPerms, setUserPerms] = useState<Record<string, {canEdit: boolean, grade: {canGrade: boolean, reviewerRole: string | null}}>>({});

    const loadData = useCallback(async () => {
        const [p, s, t, r, st, f, pt] = await Promise.all([
            db.getProjects(), db.getStudents(), db.getTeachers(),
            db.getTeacherRoles(), db.getStatuses(), db.getFormats(),
            db.getProjectTeachers()
        ]);
        setProjects(p);
        setStudents(s);
        setTeachers(t);
        setRoles(r);
        setStatuses(st);
        setFormats(f);
        setProjectTeachers(pt);

        const perms: any = {};
        for(const project of p) {
            perms[project.id] = {
                canEdit: await canEditProject(project.id),
                grade: await canGradeProject(project.id)
            };
        }
        setUserPerms(perms);
    }, [canEditProject, canGradeProject]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>) => {
        let savedProject: Project;
        if (editingProject) {
            savedProject = await db.updateProject({ ...editingProject, ...projectData } as Project);
        } else {
            savedProject = await db.addProject(projectData as Omit<Project, 'id'>);
        }

        if (userPerms[savedProject.id]?.canEdit || isAdmin) {
            await db.deleteProjectTeachersByProject(savedProject.id);
            for (const a of assignments) {
                await db.addProjectTeacher({ projectId: savedProject.id, teacherId: a.teacherId, roleId: a.roleId });
            }
        }

        loadData();
        setIsModalOpen(false);
    };

    const handleDelete = async () => {
        if (deletingProject) {
            await db.deleteProject(deletingProject.id);
            loadData();
            setDeletingProject(null);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h1 className="text-3xl font-bold">Proyectos</h1>
                {isAdmin && <button onClick={() => { setEditingProject(null); setIsModalOpen(true); }} className="bg-primary-600 text-white px-4 py-2 rounded flex items-center"><PlusIcon className="h-5 w-5 mr-1"/> Nuevo</button>}
            </div>
            <div className="bg-white shadow rounded-lg overflow-x-auto">
                <table className="w-full">
                    <thead className="bg-gray-50 border-b">
                        <tr>
                            <th className="px-6 py-3 text-left text-xs text-gray-500 uppercase">Título</th>
                            <th className="px-6 py-3 text-left text-xs text-gray-500 uppercase">Estado</th>
                            <th className="px-6 py-3 text-left text-xs text-gray-500 uppercase">Acciones</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y">
                        {projects.map(p => (
                            <tr key={p.id}>
                                <td className="px-6 py-4">{p.title}</td>
                                <td className="px-6 py-4">{statuses.find(s => s.id === p.statusId)?.name}</td>
                                <td className="px-6 py-4 flex gap-2">
                                    {(userPerms[p.id]?.canEdit || userPerms[p.id]?.grade.canGrade) && <button onClick={() => { setEditingProject(p); setIsModalOpen(true); }} className="text-primary-600"><EditIcon className="h-5 w-5"/></button>}
                                    {userPerms[p.id]?.canEdit && <button onClick={() => setDeletingProject(p)} className="text-red-600"><TrashIcon className="h-5 w-5"/></button>}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingProject ? 'Editar Proyecto' : 'Nuevo Proyecto'}>
                {isModalOpen && <ProjectForm project={editingProject} onSave={handleSave} onClose={() => setIsModalOpen(false)} statuses={statuses} formats={formats} teachers={teachers} roles={roles} initialAssignments={editingProject ? projectTeachers.filter(pt => pt.projectId === editingProject.id) : []} canEditDetails={editingProject ? userPerms[editingProject.id]?.canEdit : isAdmin} gradeInfo={editingProject ? userPerms[editingProject.id]?.grade : {canGrade: false, reviewerRole: null}} />}
            </Modal>
            <ConfirmationDialog isOpen={!!deletingProject} onClose={() => setDeletingProject(null)} onConfirm={handleDelete} title="Eliminar" message="¿Confirmas la eliminación del proyecto?" />
        </div>
    );
};

