import { createClient } from '@supabase/supabase-js';
import { Project, Student, Teacher, ProjectTeacher, Format, TeacherRole, Status, Program, User } from '../types';

const supabaseUrl = process.env.SUPABASE_URL || '';
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || '';

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

const generateId = (): string => Date.now().toString(36) + Math.random().toString(36).substring(2);

// Mapeo de campos CamelCase a snake_case para Supabase si es necesario, 
// o simplemente asegurar que las tablas coincidan.
// Para este ejemplo, asumiremos que las tablas usan los nombres de las interfaces.

// Fix: Export initializeDB as a named export for App.tsx
export const initializeDB = () => { /* No-op con Supabase real */ };

export const db = {
    // Auth & Users
    getUsers: async () => {
        const { data } = await supabase.from('users').select('*');
        return data || [];
    },
    getUserByUsername: async (username: string) => {
        const { data } = await supabase.from('users').select('*').ilike('username', username).single();
        return data;
    },
    deleteUser: async (id: string) => {
        await supabase.from('users').delete().eq('id', id);
    },

    // Projects
    getProjects: async () => {
        const { data } = await supabase.from('projects').select('*');
        return data || [];
    },
    getProjectById: async (id: string) => {
        const { data } = await supabase.from('projects').select('*').eq('id', id).single();
        return data;
    },
    addProject: async (project: Omit<Project, 'id'>) => {
        const id = generateId();
        const { data } = await supabase.from('projects').insert([{ ...project, id }]).select().single();
        return data;
    },
    updateProject: async (project: Project) => {
        const { data } = await supabase.from('projects').update(project).eq('id', project.id).select().single();
        return data;
    },
    deleteProject: async (id: string) => {
        // La lógica de cascada se recomienda manejarla en Supabase (ON DELETE SET NULL/CASCADE)
        await supabase.from('projects').delete().eq('id', id);
    },

    // Students
    getStudents: async () => {
        const { data } = await supabase.from('students').select('*');
        return data || [];
    },
    getStudentById: async (id: string) => {
        const { data } = await supabase.from('students').select('*').eq('id', id).single();
        return data;
    },
    addStudent: async (student: Omit<Student, 'id'>) => {
        const id = generateId();
        const { data: newStudent } = await supabase.from('students').insert([{ ...student, id }]).select().single();

        // Crear usuario automático
        const userId = generateId();
        await supabase.from('users').insert([{
            id: userId,
            username: student.email.split('@')[0],
            password: student.cedula,
            role: 'student',
            studentId: id
        }]);

        return newStudent;
    },
    updateStudent: async (student: Student) => {
        const { data } = await supabase.from('students').update(student).eq('id', student.id).select().single();
        // Actualizar usuario asociado
        await supabase.from('users').update({
            username: student.email.split('@')[0],
            password: student.cedula
        }).eq('studentId', student.id);
        return data;
    },
    deleteStudent: async (id: string) => {
        await supabase.from('users').delete().eq('studentId', id);
        await supabase.from('students').delete().eq('id', id);
    },

    // Teachers
    getTeachers: async () => {
        const { data } = await supabase.from('teachers').select('*');
        return data || [];
    },
    getTeacherById: async (id: string) => {
        const { data } = await supabase.from('teachers').select('*').eq('id', id).single();
        return data;
    },
    addTeacher: async (teacher: Omit<Teacher, 'id'>) => {
        const id = generateId();
        const { data: newTeacher } = await supabase.from('teachers').insert([{ ...teacher, id }]).select().single();

        // Crear usuario automático
        const userId = generateId();
        await supabase.from('users').insert([{
            id: userId,
            username: teacher.email.split('@')[0],
            password: teacher.cedula,
            role: 'teacher',
            teacherId: id
        }]);

        return newTeacher;
    },
    updateTeacher: async (teacher: Teacher) => {
        const { data } = await supabase.from('teachers').update(teacher).eq('id', teacher.id).select().single();
        await supabase.from('users').update({
            username: teacher.email.split('@')[0],
            password: teacher.cedula
        }).eq('teacherId', teacher.id);
        return data;
    },
    deleteTeacher: async (id: string) => {
        await supabase.from('users').delete().eq('teacherId', id);
        await supabase.from('teachers').delete().eq('id', id);
    },

    // Project Teachers (Union Table)
    getProjectTeachers: async () => {
        const { data } = await supabase.from('project_teachers').select('*');
        return data || [];
    },
    addProjectTeacher: async (pt: Omit<ProjectTeacher, 'id'>) => {
        const id = generateId();
        const { data } = await supabase.from('project_teachers').insert([{ ...pt, id }]).select().single();
        return data;
    },
    deleteProjectTeacher: async (id: string) => {
        await supabase.from('project_teachers').delete().eq('id', id);
    },
    deleteProjectTeachersByProject: async (projectId: string) => {
        await supabase.from('project_teachers').delete().eq('project_id', projectId);
    },

    // catalogs
    getPrograms: async () => (await supabase.from('programs').select('*')).data || [],
    getStatuses: async () => (await supabase.from('statuses').select('*')).data || [],
    getFormats: async () => (await supabase.from('formats').select('*')).data || [],
    getTeacherRoles: async () => (await supabase.from('teacher_roles').select('*')).data || [],

    addProgram: async (p: Omit<Program, 'id'>) => (await supabase.from('programs').insert([{...p, id: generateId()}]).select().single()).data,
    updateProgram: async (p: Program) => (await supabase.from('programs').update(p).eq('id', p.id).select().single()).data,
    deleteProgram: async (id: string) => await supabase.from('programs').delete().eq('id', id),

    addStatus: async (p: Omit<Status, 'id'>) => (await supabase.from('statuses').insert([{...p, id: generateId()}]).select().single()).data,
    updateStatus: async (p: Status) => (await supabase.from('statuses').update(p).eq('id', p.id).select().single()).data,
    deleteStatus: async (id: string) => await supabase.from('statuses').delete().eq('id', id),

    addFormat: async (p: Omit<Format, 'id'>) => (await supabase.from('formats').insert([{...p, id: generateId()}]).select().single()).data,
    updateFormat: async (p: Format) => (await supabase.from('formats').update(p).eq('id', p.id).select().single()).data,
    deleteFormat: async (id: string) => await supabase.from('formats').delete().eq('id', id),

    addTeacherRole: async (p: Omit<TeacherRole, 'id'>) => (await supabase.from('teacher_roles').insert([{...p, id: generateId()}]).select().single()).data,
    updateTeacherRole: async (p: TeacherRole) => (await supabase.from('teacher_roles').update(p).eq('id', p.id).select().single()).data,
    deleteTeacherRole: async (id: string) => await supabase.from('teacher_roles').delete().eq('id', id),

    // Fix: Add getCurrentDB to support data management features in SettingsPage
    getCurrentDB: async () => {
        const [users, projects, programs, students, teachers, projectTeachers, formats, teacherRoles, statuses] = await Promise.all([
            db.getUsers(), db.getProjects(), db.getPrograms(), db.getStudents(), db.getTeachers(),
            db.getProjectTeachers(), db.getFormats(), db.getTeacherRoles(), db.getStatuses()
        ]);
        return { users, projects, programs, students, teachers, projectTeachers, formats, teacherRoles, statuses };
    },

    // Helpers
    initializeDB
};

import React, { useState, useEffect } from 'react';
import { db } from './services/database';
import { Sidebar } from './components/Sidebar';
import { DashboardPage } from './pages/DashboardPage';
import { ProjectsPage } from './pages/ProjectsPage';
import { StudentsPage } from './pages/StudentsPage';
import { TeachersPage } from './pages/TeachersPage';
import { SettingsPage } from './pages/SettingsPage';
import { ReportsPage } from './pages/ReportsPage';
import { UsersPage } from './pages/UsersPage';
import { MenuIcon, XIcon } from './components/Icons';
import { useAuth } from './contexts/AuthContext';
import { LoginPage } from './pages/LoginPage';
import { StudentProjectViewPage } from './pages/StudentProjectViewPage';

type Page = 'dashboard' | 'projects' | 'students' | 'teachers' | 'settings' | 'reports' | 'users';

const pageLabels: Record<Page, string> = {
    dashboard: 'Panel Principal',
    projects: 'Proyectos',
    students: 'Estudiantes',
    teachers: 'Docentes',
    settings: 'Configuración',
    reports: 'Reportes',
    users: 'Usuarios',
};

const App: React.FC = () => {
  const { isAuthenticated, logout, isStudent } = useAuth();
  const [currentPage, setCurrentPage] = useState<Page>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    // Fix: Used db.initializeDB() instead of an unexported direct function to properly initialize with Supabase
    db.initializeDB();
  }, []);

  if (!isAuthenticated) {
    return <LoginPage />;
  }

  if (isStudent) {
    return <StudentProjectViewPage />;
  }

  const renderPage = () => {
    switch (currentPage) {
      case 'dashboard':
        return <DashboardPage />;
      case 'projects':
        return <ProjectsPage />;
      case 'students':
        return <StudentsPage />;
      case 'teachers':
        return <TeachersPage />;
      case 'settings':
        return <SettingsPage />;
      case 'reports':
        return <ReportsPage />;
      case 'users':
        return <UsersPage />;
      default:
        return <DashboardPage />;
    }
  };

  const handlePageChange = (page: Page) => {
    setCurrentPage(page);
    if (window.innerWidth < 768) {
      setIsSidebarOpen(false);
    }
  }

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      <Sidebar 
        currentPage={currentPage} 
        onNavigate={handlePageChange}
        isOpen={isSidebarOpen}
        setIsOpen={setIsSidebarOpen}
      />
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="flex justify-between items-center p-4 bg-white border-b">
           <div className="flex items-center">
             <button 
                className="md:hidden mr-4 text-gray-500 hover:text-gray-600 focus:outline-none focus:ring-2 focus:ring-primary-500"
                onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              >
                {isSidebarOpen ? <XIcon className="h-6 w-6" /> : <MenuIcon className="h-6 w-6" />}
              </button>
              <div className="text-xl font-semibold text-gray-700">
                {pageLabels[currentPage]}
              </div>
          </div>
          <button
            onClick={logout}
            className="px-4 py-2 text-sm bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-400"
          >
            Cerrar Sesión
          </button>
        </header>
        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 p-4 md:p-6">
          {renderPage()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { Status, Format, TeacherRole, AppDatabase, Program, Student } from '../types';
import { EditIcon, TrashIcon, PlusIcon } from '../components/Icons';
import { ConfirmationDialog } from '../components/ConfirmationDialog';
import { useAuth } from '../contexts/AuthContext';

type EntityType = 'status' | 'format' | 'role' | 'program';
type Entity = Status | Format | TeacherRole | Program;

interface SettingsListProps<T extends Entity> {
    title: string;
    items: T[];
    placeholder: string;
    onAdd: (name: string) => void;
    onUpdate: (item: T) => void;
    onDelete: (item: T) => void;
}

const SettingsList = <T extends {id: string; name: string}>({ title, items, placeholder, onAdd, onUpdate, onDelete }: SettingsListProps<T>) => {
    const { isAdmin } = useAuth();
    const [newItemName, setNewItemName] = useState('');
    const [editingItem, setEditingItem] = useState<T | null>(null);

    const handleAdd = () => {
        if (newItemName.trim()) {
            onAdd(newItemName.trim());
            setNewItemName('');
        }
    };

    const handleUpdate = () => {
        if (editingItem && editingItem.name.trim()){
            onUpdate(editingItem);
            setEditingItem(null);
        }
    }

    return (
        <div className="bg-white rounded-lg shadow p-6">
            <h2 className="text-xl font-semibold text-gray-800 mb-4">{title}</h2>
            {isAdmin && (
                <div className="flex space-x-2 mb-4">
                    <input
                        type="text"
                        value={newItemName}
                        onChange={(e) => setNewItemName(e.target.value)}
                        placeholder={placeholder}
                        className="flex-grow border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-primary-500 focus:border-primary-500"
                    />
                    <button onClick={handleAdd} className="flex-shrink-0 bg-primary-600 text-white px-4 py-2 rounded-md hover:bg-primary-700 flex items-center">
                        <PlusIcon className="h-5 w-5"/>
                    </button>
                </div>
            )}
            <ul className="divide-y divide-gray-200">
                {items.map(item => (
                    <li key={item.id} className="py-3 flex justify-between items-center">
                        {editingItem?.id === item.id && isAdmin ? (
                           <input 
                            type="text"
                            value={editingItem.name}
                            onChange={(e) => setEditingItem({...editingItem, name: e.target.value})}
                            onBlur={handleUpdate}
                            onKeyDown={(e) => e.key === 'Enter' && handleUpdate()}
                            autoFocus
                            className="text-sm text-gray-800 border-b border-primary-500 focus:outline-none"
                           />
                        ) : (
                            <span className="text-sm text-gray-800">{item.name}</span>
                        )}
                        {isAdmin && (
                            <div className="space-x-2">
                                <button onClick={() => setEditingItem(item)} className="text-primary-600 hover:text-primary-900"><EditIcon className="h-5 w-5" /></button>
                                <button onClick={() => onDelete(item)} className="text-red-600 hover:text-red-900"><TrashIcon className="h-5 w-5" /></button>
                            </div>
                        )}
                    </li>
                ))}
            </ul>
        </div>
    );
};

const DataManagement: React.FC = () => {
    const { isAdmin } = useAuth();
    const [seedCode, setSeedCode] = useState<string | null>(null);
    const [copySuccess, setCopySuccess] = useState(false);

    // Fix: Make handleGenerateSeedCode async to handle the Promise returned by db.getCurrentDB()
    const handleGenerateSeedCode = async () => {
        const currentDb = await db.getCurrentDB();
        // Remove IDs to allow regeneration on import, except for specific seed users/entities
        const dbForExport = JSON.parse(JSON.stringify(currentDb));
        const codeString = `const getSeedData = (): AppDatabase => {\n  // Código generado el ${new Date().toLocaleString()}\n  return ${JSON.stringify(dbForExport, null, 2)};\n};`;
        setSeedCode(`// Para actualizar los datos de inicio, reemplace el contenido de la función getSeedData() en services/database.ts con el siguiente código:\n\n${codeString}`);
        setCopySuccess(false);
    };

    const handleCopyToClipboard = () => {
        if (seedCode) {
            navigator.clipboard.writeText(seedCode).then(() => {
                setCopySuccess(true);
                setTimeout(() => setCopySuccess(false), 2000);
            }, (err) => {
                console.error('Error al copiar al portapapeles: ', err);
                alert('No se pudo copiar el código.');
            });
        }
    };


    if (!isAdmin) {
        return null;
    }

    return (
        <div className="bg-white rounded-lg shadow p-6">
            <h2 className="text-xl font-semibold text-gray-800 mb-2">Gestión de Datos de Inicio</h2>
            <p className="text-sm text-gray-600 mb-6">
                Para actualizar los datos iniciales para todos los usuarios (ej. añadir nuevos usuarios por defecto), sigue estos pasos. 
                Esto es útil para preparar la aplicación antes de un despliegue en Vercel.
            </p>

            <div className="p-4 border-l-4 border-primary-500 bg-primary-50 rounded-md">
                <h3 className="text-lg font-medium text-primary-800">Generar Código de Datos de Inicio</h3>
                <p className="text-sm text-primary-700 mt-1 mb-3">
                    1. Realiza todos los cambios que desees en la aplicación (añadir usuarios, proyectos, etc.).<br/>
                    2. Haz clic en el botón de abajo para generar el código que representa el estado actual.<br/>
                    3. Copia el código generado y reemplaza el contenido de la función `getSeedData` en el archivo `services/database.ts`.<br/>
                    4. Despliega tu aplicación en Vercel. Los nuevos datos de inicio se cargarán para todos los nuevos visitantes.
                </p>
                <button 
                    onClick={handleGenerateSeedCode}
                    className="bg-primary-600 text-white px-4 py-2 rounded-md hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 text-sm font-medium"
                >
                    Generar Código
                </button>
            </div>

            {seedCode && (
                <div className="mt-6">
                     <h3 className="text-lg font-medium text-gray-700 mb-2">Código Generado</h3>
                    <div className="relative">
                        <textarea
                            readOnly
                            value={seedCode}
                            className="w-full h-64 p-4 font-mono text-xs bg-gray-900 text-gray-100 rounded-md border border-gray-700 focus:ring-primary-500 focus:border-primary-500"
                        />
                         <button 
                            onClick={handleCopyToClipboard}
                            className="absolute top-3 right-3 bg-gray-700 text-white px-3 py-1 rounded-md text-xs hover:bg-gray-600"
                        >
                            {copySuccess ? '¡Copiado!' : 'Copiar'}
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export const SettingsPage: React.FC = () => {
    const { isAdmin } = useAuth();
    const [statuses, setStatuses] = useState<Status[]>([]);
    const [formats, setFormats] = useState<Format[]>([]);
    const [roles, setRoles] = useState<TeacherRole[]>([]);
    const [programs, setPrograms] = useState<Program[]>([]);
    const [students, setStudents] = useState<Student[]>([]);
    const [deletingItem, setDeletingItem] = useState<{item: Entity, type: EntityType} | null>(null);

    // Fix: Made loadData async to properly await and resolve database promises
    const loadData = useCallback(async () => {
        const [s, f, r, p, st] = await Promise.all([
            db.getStatuses(), db.getFormats(), db.getTeacherRoles(), db.getPrograms(), db.getStudents()
        ]);
        setStatuses(s);
        setFormats(f);
        setRoles(r);
        setPrograms(p);
        setStudents(st);
    }, []);

    useEffect(() => {
        loadData();
    }, [loadData]);

    const handleAdd = async (type: EntityType, name: string) => {
        if (!isAdmin) return;
        if(type === 'status') await db.addStatus({ name });
        if(type === 'format') await db.addFormat({ name });
        if(type === 'role') await db.addTeacherRole({ name });
        if(type === 'program') await db.addProgram({ name });
        loadData();
    };

    const handleUpdate = async (type: EntityType, item: Entity) => {
        if (!isAdmin) return;
        if(type === 'status') await db.updateStatus(item as Status);
        if(type === 'format') await db.updateFormat(item as Format);
        if(type === 'role') await db.updateTeacherRole(item as TeacherRole);
        if(type === 'program') await db.updateProgram(item as Program);
        loadData();
    };

    const handleDelete = async () => {
        if (!deletingItem || !isAdmin) return;
        const { item, type } = deletingItem;

        if(type === 'status') await db.deleteStatus(item.id);
        if(type === 'format') await db.deleteFormat(item.id);
        if(type === 'role') await db.deleteTeacherRole(item.id);
        if(type === 'program') await db.deleteProgram(item.id);

        loadData();
        setDeletingItem(null);
    }

    const getEntityTypeSpanish = (type: EntityType | undefined) => {
        if (!type) return '';
        switch (type) {
            case 'status': return 'Estado';
            case 'format': return 'Formato';
            case 'role': return 'Rol';
            case 'program': return 'Programa Académico';
            default: return '';
        }
    }

    return (
        <div className="space-y-6">
            <h1 className="text-3xl font-bold text-gray-800">Configuración</h1>
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">
                <SettingsList
                    title="Estados de Proyecto"
                    items={statuses}
                    placeholder="Nuevo nombre de estado"
                    onAdd={(name) => handleAdd('status', name)}
                    onUpdate={(item) => handleUpdate('status', item)}
                    onDelete={(item) => setDeletingItem({item, type: 'status'})}
                />
                <SettingsList
                    title="Formatos de Proyecto"
                    items={formats}
                    placeholder="Nuevo nombre de formato"
                    onAdd={(name) => handleAdd('format', name)}
                    onUpdate={(item) => handleUpdate('format', item)}
                    onDelete={(item) => setDeletingItem({item, type: 'format'})}
                />
                <SettingsList
                    title="Roles de Docente"
                    items={roles}
                    placeholder="Nuevo nombre de rol"
                    onAdd={(name) => handleAdd('role', name)}
                    onUpdate={(item) => handleUpdate('role', item)}
                    onDelete={(item) => setDeletingItem({item, type: 'role'})}
                />
                <SettingsList
                    title="Programas Académicos"
                    items={programs}
                    placeholder="Nuevo programa académico"
                    onAdd={(name) => handleAdd('program', name)}
                    onUpdate={(item) => handleUpdate('program', item)}
                    onDelete={(item) => {
                        const isProgramInUse = students.some(s => s.programId === item.id);
                        if (isProgramInUse) {
                            alert('No se puede eliminar este programa académico porque está asignado a uno o más estudiantes.');
                            return;
                        }
                        setDeletingItem({item, type: 'program'});
                    }}
                />
            </div>
            <div className="mt-6">
                <DataManagement />
            </div>
            <ConfirmationDialog
                isOpen={!!deletingItem}
                onClose={() => setDeletingItem(null)}
                onConfirm={handleDelete}
                title={`Eliminar ${getEntityTypeSpanish(deletingItem?.type)}`}
                message={`¿Estás seguro de que quieres eliminar "${deletingItem?.item.name}"? Esto podría afectar a los proyectos y estudiantes existentes.`}
            />
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { db } from '../services/database';
import { Project, Student, Teacher, TeacherRole, Status, Format, ProjectTeacher, Program } from '../types';
import { arrayToCsv } from '../utils/csv';

// Informa a TypeScript sobre la variable global Chart de la CDN
declare var Chart: any;

// --- Interfaces para los datos de los reportes ---
interface ProjectStatusReport {
    'Título del Proyecto': string;
    'Estado': string;
    'Formato': string;
    'Fecha de Presentación': string;
