import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { db } from '../services/database';
import { Student, Project, Status, ProjectTeacher, Teacher, TeacherRole } from '../types';
import { ProjectIcon } from '../components/Icons';

export const StudentProjectViewPage: React.FC = () => {
    const { user, logout } = useAuth();
    const [student, setStudent] = useState<Student | null>(null);
    const [project, setProject] = useState<Project | null>(null);
    const [status, setStatus] = useState<Status | null>(null);
    const [directors, setDirectors] = useState<Teacher[]>([]);

    useEffect(() => {
        // Fix: Created an async wrapper function within useEffect to handle asynchronous database calls and resolve Promise<any> errors
        const loadViewData = async () => {
            if (user?.studentId) {
                const studentData = await db.getStudentById(user.studentId);
                setStudent(studentData || null);

                if (studentData?.projectId) {
                    const projectData = await db.getProjectById(studentData.projectId);
                    setProject(projectData || null);

                    if (projectData) {
                        const allStatuses = await db.getStatuses();
                        const statusData = allStatuses.find(s => s.id === projectData.statusId);
                        setStatus(statusData || null);

                        const allProjectTeachers = await db.getProjectTeachers();
                        const projectTeachers = allProjectTeachers.filter(pt => pt.projectId === projectData.id);
                        const allTeachers = await db.getTeachers();
                        const allRoles = await db.getTeacherRoles();
                        const directorRoles = allRoles.filter(r => r.name.toLowerCase().includes('director')).map(r => r.id);

                        const assignedDirectors = projectTeachers
                            .filter(pt => directorRoles.includes(pt.roleId))
                            .map(pt => allTeachers.find(t => t.id === pt.teacherId))
                            .filter((t): t is Teacher => !!t);

                        setDirectors(assignedDirectors);
                    }
                }
            }
        };

        loadViewData();
    }, [user]);

    return (
        <div className="min-h-screen bg-gray-100 font-sans">
            <header className="flex justify-between items-center p-4 bg-white shadow-md">
                <div className="flex items-center">
                    <ProjectIcon className="h-8 w-8 text-primary-600" />
                    <h1 className="text-xl font-bold text-gray-800 ml-3">Estado de Mi Proyecto</h1>
                </div>
                <button
                    onClick={logout}
                    className="px-4 py-2 text-sm bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-400"
                >
                    Cerrar Sesión
                </button>
            </header>
            <main className="p-4 md:p-8">
                <div className="max-w-4xl mx-auto bg-white rounded-lg shadow-lg p-6 md:p-8">
                    <div className="text-center mb-8">
                        <h2 className="text-2xl font-semibold text-gray-700">Bienvenido, {student?.name || 'Estudiante'}</h2>
                        <p className="text-gray-500 mt-1">Aquí puedes consultar la información actual de tu proyecto de grado.</p>
                    </div>

                    {project ? (
                        <div className="space-y-6">
                            <div>
                                <h3 className="text-sm font-medium text-gray-500 uppercase tracking-wider">Título del Proyecto</h3>
                                <p className="text-xl text-gray-800 mt-1">{project.title}</p>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <h3 className="text-sm font-medium text-gray-500 uppercase tracking-wider">Estado Actual</h3>
                                    {status && (
                                        <span className="mt-2 inline-flex items-center px-3 py-1 text-base font-semibold rounded-full bg-blue-100 text-blue-800">
                                            {status.name}
                                        </span>
                                    )}
                                </div>
                                <div>
                                    <h3 className="text-sm font-medium text-gray-500 uppercase tracking-wider">Director(es) Asignados</h3>
                                    {directors.length > 0 ? (
                                        <ul className="mt-1 space-y-1">
                                        {directors.map(d => (
                                            <li key={d.id} className="text-lg text-gray-800">{d.name}</li>
                                        ))}
                                        </ul>
                                    ) : (
                                         <p className="text-lg text-gray-500 italic mt-1">No asignados</p>
                                    )}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="text-center py-10">
                            <p className="text-lg text-gray-600">Aún no tienes un proyecto de grado asignado.</p>
                            <p className="text-sm text-gray-500 mt-2">Por favor, contacta a tu director de programa para más información.</p>
                        </div>
                    )}
                </div>
            </main>
        </div>
    );
};

import { createClient } from '@supabase/supabase-js';
import { Project, Student, Teacher, ProjectTeacher, Format, TeacherRole, Status, Program, User } from '../types';

const supabaseUrl = process.env.SUPABASE_URL || '';
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || '';

// Inicializar de forma segura para evitar el error de "URL required" en entornos sin configurar
export const isSupabaseConfigured = !!(supabaseUrl && supabaseAnonKey);
export const supabase = isSupabaseConfigured 
    ? createClient(supabaseUrl, supabaseAnonKey) 
    : null as any;

const generateId = (): string => Date.now().toString(36) + Math.random().toString(36).substring(2);

// Fix: Export initializeDB as a named export for App.tsx
export const initializeDB = () => { 
    if (!isSupabaseConfigured) {
        console.warn('Supabase no está configurado. Por favor, añade SUPABASE_URL y SUPABASE_ANON_KEY a tus variables de entorno.');
    }
};

export const db = {
    // Auth & Users
    getUsers: async () => {
        if (!supabase) return [];
        const { data } = await supabase.from('users').select('*');
        return data || [];
    },
    getUserByUsername: async (username: string) => {
        if (!supabase) return null;
        const { data } = await supabase.from('users').select('*').ilike('username', username).single();
        return data;
    },
    deleteUser: async (id: string) => {
        if (!supabase) return;
        await supabase.from('users').delete().eq('id', id);
    },

    // Projects
    getProjects: async () => {
        if (!supabase) return [];
        const { data } = await supabase.from('projects').select('*');
        return data || [];
    },
    getProjectById: async (id: string) => {
        if (!supabase) return null;
        const { data } = await supabase.from('projects').select('*').eq('id', id).single();
        return data;
    },
    addProject: async (project: Omit<Project, 'id'>) => {
        if (!supabase) throw new Error("Database not configured");
        const id = generateId();
        const { data } = await supabase.from('projects').insert([{ ...project, id }]).select().single();
        return data;
    },
    updateProject: async (project: Project) => {
        if (!supabase) throw new Error("Database not configured");
        const { data } = await supabase.from('projects').update(project).eq('id', project.id).select().single();
        return data;
    },
    deleteProject: async (id: string) => {
        if (!supabase) return;
        await supabase.from('projects').delete().eq('id', id);
    },

    // Students
    getStudents: async () => {
        if (!supabase) return [];
        const { data } = await supabase.from('students').select('*');
        return data || [];
    },
    getStudentById: async (id: string) => {
        if (!supabase) return null;
        const { data } = await supabase.from('students').select('*').eq('id', id).single();
        return data;
    },
    addStudent: async (student: Omit<Student, 'id'>) => {
        if (!supabase) throw new Error("Database not configured");
        const id = generateId();
        const { data: newStudent } = await supabase.from('students').insert([{ ...student, id }]).select().single();

        // Crear usuario automático
        const userId = generateId();
        await supabase.from('users').insert([{
            id: userId,
            username: student.email.split('@')[0],
            password: student.cedula,
            role: 'student',
            studentId: id
        }]);

        return newStudent;
    },
    updateStudent: async (student: Student) => {
        if (!supabase) throw new Error("Database not configured");
        const { data } = await supabase.from('students').update(student).eq('id', student.id).select().single();
        await supabase.from('users').update({
            username: student.email.split('@')[0],
            password: student.cedula
        }).eq('studentId', student.id);
        return data;
    },
    deleteStudent: async (id: string) => {
        if (!supabase) return;
        await supabase.from('users').delete().eq('studentId', id);
        await supabase.from('students').delete().eq('id', id);
    },

    // Teachers
    getTeachers: async () => {
        if (!supabase) return [];
        const { data } = await supabase.from('teachers').select('*');
        return data || [];
    },
    getTeacherById: async (id: string) => {
        if (!supabase) return null;
        const { data } = await supabase.from('teachers').select('*').eq('id', id).single();
        return data;
    },
    addTeacher: async (teacher: Omit<Teacher, 'id'>) => {
        if (!supabase) throw new Error("Database not configured");
        const id = generateId();
        const { data: newTeacher } = await supabase.from('teachers').insert([{ ...teacher, id }]).select().single();

        // Crear usuario automático
        const userId = generateId();
        await supabase.from('users').insert([{
            id: userId,
            username: teacher.email.split('@')[0],
            password: teacher.cedula,
            role: 'teacher',
            teacherId: id
        }]);

        return newTeacher;
    },
    updateTeacher: async (teacher: Teacher) => {
        if (!supabase) throw new Error("Database not configured");
        const { data } = await supabase.from('teachers').update(teacher).eq('id', teacher.id).select().single();
        await supabase.from('users').update({
            username: teacher.email.split('@')[0],
            password: teacher.cedula
        }).eq('teacherId', teacher.id);
        return data;
    },
    deleteTeacher: async (id: string) => {
        if (!supabase) return;
        await supabase.from('users').delete().eq('teacherId', id);
        await supabase.from('teachers').delete().eq('id', id);
    },

    // Project Teachers (Union Table)
    getProjectTeachers: async () => {
        if (!supabase) return [];
        const { data } = await supabase.from('project_teachers').select('*');
        return data || [];
    },
    addProjectTeacher: async (pt: Omit<ProjectTeacher, 'id'>) => {
        if (!supabase) throw new Error("Database not configured");
        const id = generateId();
        const { data } = await supabase.from('project_teachers').insert([{ ...pt, id }]).select().single();
        return data;
    },
    deleteProjectTeacher: async (id: string) => {
        if (!supabase) return;
        await supabase.from('project_teachers').delete().eq('id', id);
    },
    deleteProjectTeachersByProject: async (projectId: string) => {
        if (!supabase) return;
        await supabase.from('project_teachers').delete().eq('project_id', projectId);
    },

    // Catalogs
    getPrograms: async () => {
        if (!supabase) return [];
        return (await supabase.from('programs').select('*')).data || [];
    },
    getStatuses: async () => {
        if (!supabase) return [];
        return (await supabase.from('statuses').select('*')).data || [];
    },
    getFormats: async () => {
        if (!supabase) return [];
        return (await supabase.from('formats').select('*')).data || [];
    },
    getTeacherRoles: async () => {
        if (!supabase) return [];
        return (await supabase.from('teacher_roles').select('*')).data || [];
    },

    addProgram: async (p: Omit<Program, 'id'>) => {
        if (!supabase) return null;
        return (await supabase.from('programs').insert([{...p, id: generateId()}]).select().single()).data;
    },
    updateProgram: async (p: Program) => {
        if (!supabase) return null;
        return (await supabase.from('programs').update(p).eq('id', p.id).select().single()).data;
    },
    deleteProgram: async (id: string) => {
        if (!supabase) return;
        await supabase.from('programs').delete().eq('id', id);
    },

    addStatus: async (p: Omit<Status, 'id'>) => {
        if (!supabase) return null;
        return (await supabase.from('statuses').insert([{...p, id: generateId()}]).select().single()).data;
    },
    updateStatus: async (p: Status) => {
        if (!supabase) return null;
        return (await supabase.from('statuses').update(p).eq('id', p.id).select().single()).data;
    },
    deleteStatus: async (id: string) => {
        if (!supabase) return;
        await supabase.from('statuses').delete().eq('id', id);
    },

    addFormat: async (p: Omit<Format, 'id'>) => {
        if (!supabase) return null;
        return (await supabase.from('formats').insert([{...p, id: generateId()}]).select().single()).data;
    },
    updateFormat: async (p: Format) => {
        if (!supabase) return null;
        return (await supabase.from('formats').update(p).eq('id', p.id).select().single()).data;
    },
    deleteFormat: async (id: string) => {
        if (!supabase) return;
        await supabase.from('formats').delete().eq('id', id);
    },

    addTeacherRole: async (p: Omit<TeacherRole, 'id'>) => {
        if (!supabase) return null;
        return (await supabase.from('teacher_roles').insert([{...p, id: generateId()}]).select().single()).data;
    },
    updateTeacherRole: async (p: TeacherRole) => {
        if (!supabase) return null;
        return (await supabase.from('teacher_roles').update(p).eq('id', p.id).select().single()).data;
    },
    deleteTeacherRole: async (id: string) => {
        if (!supabase) return;
        await supabase.from('teacher_roles').delete().eq('id', id);
    },

    getCurrentDB: async () => {
        const [users, projects, programs, students, teachers, projectTeachers, formats, teacherRoles, statuses] = await Promise.all([
            db.getUsers(), db.getProjects(), db.getPrograms(), db.getStudents(), db.getTeachers(),
            db.getProjectTeachers(), db.getFormats(), db.getTeacherRoles(), db.getStatuses()
        ]);
        return { users, projects, programs, students, teachers, projectTeachers, formats, teacherRoles, statuses };
    },

    initializeDB
};

import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';

export const LoginPage: React.FC = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const { login } = useAuth();

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);
        try {
            const success = await login(username, password);
            if (!success) {
                setError('Usuario o contraseña incorrectos.');
            }
        } catch (err) {
            setError('Error de conexión con el servidor.');
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="flex items-center justify-center min-h-screen bg-gray-100">
            <div className="w-full max-w-md p-8 space-y-8 bg-white rounded-lg shadow-lg">
                <div className="text-center">
                    <h1 className="text-3xl font-bold text-gray-900">Gestor de Proyectos</h1>
                    <p className="mt-2 text-sm text-gray-600">Inicia sesión para continuar</p>
                </div>
                <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
                    <div className="rounded-md shadow-sm -space-y-px">
                        <div>
                            <label htmlFor="username" className="sr-only">Usuario</label>
                            <input
                                id="username"
                                name="username"
                                type="text"
                                required
                                value={username}
                                onChange={(e) => setUsername(e.target.value)}
                                className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 rounded-t-md focus:outline-none focus:ring-primary-500 focus:border-primary-500 focus:z-10 sm:text-sm"
                                placeholder="Usuario"
                            />
                        </div>
                        <div>
                            <label htmlFor="password" className="sr-only">Contraseña</label>
                            <input
                                id="password"
                                name="password"
                                type="password"
                                required
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 rounded-b-md focus:outline-none focus:ring-primary-500 focus:border-primary-500 focus:z-10 sm:text-sm"
                                placeholder="Contraseña"
                            />
                        </div>
                    </div>

                    {error && (
                        <p className="text-sm text-center text-red-600">{error}</p>
                    )}

                    <div>
                        <button
                            type="submit"
                            disabled={isLoading}
                            className={`group relative w-full flex justify-center py-2 px-4 border border-transparent text-sm font-medium rounded-md text-white ${isLoading ? 'bg-primary-400' : 'bg-primary-600 hover:bg-primary-700'} focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500`}
                        >
                            {isLoading ? 'Cargando...' : 'Iniciar Sesión'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { User, Teacher, Student } from '../types';
import { ConfirmationDialog } from '../components/ConfirmationDialog';
import { TrashIcon } from '../components/Icons';
import { useAuth } from '../contexts/AuthContext';

export const UsersPage: React.FC = () => {
    const { user: currentUser } = useAuth();
    const [users, setUsers] = useState<User[]>([]);
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [students, setStudents] = useState<Student[]>([]);
    const [deletingUser, setDeletingUser] = useState<User | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    const loadData = useCallback(async () => {
        setIsLoading(true);
        try {
            const [u, t, s] = await Promise.all([
                db.getUsers(),
                db.getTeachers(),
                db.getStudents()
            ]);
            setUsers(u);
            setTeachers(t);
            setStudents(s);
        } catch (error) {
            console.error("Error cargando usuarios:", error);
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        loadData();
    }, [loadData]);

    const handleDelete = async () => {
        if (deletingUser) {
            await db.deleteUser(deletingUser.id);
            loadData();
            setDeletingUser(null);
        }
    };

    const getLinkedEntityName = (user: User) => {
        if (user.role === 'teacher' && user.teacherId) {
            return teachers.find(t => t.id === user.teacherId)?.name || 'Docente no encontrado';
        }
        if (user.role === 'student' && user.studentId) {
            return students.find(s => s.id === user.studentId)?.name || 'Estudiante no encontrado';
        }
        return <span className="text-gray-400 italic">N/A</span>;
    };

    const getRoleName = (role: 'admin' | 'teacher' | 'student') => {
        switch(role) {
            case 'admin': return 'Administrador';
            case 'teacher': return 'Docente';
            case 'student': return 'Estudiante';
        }
    }

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h1 className="text-3xl font-bold text-gray-800">Cuentas de Usuario</h1>
            </div>
            <p className="text-gray-600">
                Esta es una lista de todas las cuentas de usuario en el sistema. Las cuentas de docentes y estudiantes se crean y actualizan automáticamente cuando se gestionan sus perfiles en sus respectivas secciones.
            </p>

            <div className="bg-white rounded-lg shadow overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Usuario</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Rol</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Perfil Vinculado</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Acciones</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {isLoading ? (
                                <tr>
                                    <td colSpan={4} className="text-center py-10 text-gray-500">Cargando usuarios...</td>
                                </tr>
                            ) : (
                                users.map(user => (
                                    <tr key={user.id}>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{user.username}</td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{getRoleName(user.role)}</td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{getLinkedEntityName(user)}</td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium space-x-2">
                                            {user.id !== currentUser?.id && user.role !== 'admin' && (
                                                <button onClick={() => setDeletingUser(user)} className="text-red-600 hover:text-red-900"><TrashIcon className="h-5 w-5" /></button>
                                            )}
                                        </td>
                                    </tr>
                                ))
                            )}
                             {!isLoading && users.length === 0 && (
                                <tr>
                                    <td colSpan={4} className="text-center py-10 text-gray-500">No se encontraron usuarios.</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            <ConfirmationDialog 
                isOpen={!!deletingUser}
                onClose={() => setDeletingUser(null)}
                onConfirm={handleDelete}
                title="Eliminar Usuario"
                message={`¿Estás seguro de que quieres eliminar al usuario ${deletingUser?.username}? El perfil de docente o estudiante asociado NO será eliminado. Esta acción no se puede deshacer.`}
            />
        </div>
    );
};

import { createClient } from '@supabase/supabase-js';
