    addTeacherRole: async (p: Omit<TeacherRole, 'id'>) => (await safeQuery(supabase?.from('teacher_roles').insert([{...p, id: generateId()}]).select().single() || Promise.resolve({data: null}))).data,
    updateTeacherRole: async (p: TeacherRole) => (await safeQuery(supabase?.from('teacher_roles').update(p).eq('id', p.id).select().single() || Promise.resolve({data: null}))).data,
    deleteTeacherRole: async (id: string) => await safeQuery(supabase?.from('teacher_roles').delete().eq('id', id) || Promise.resolve({})),

    getCurrentDB: async () => {
        const [users, projects, programs, students, teachers, projectTeachers, formats, teacherRoles, statuses] = await Promise.all([
            db.getUsers(), db.getProjects(), db.getPrograms(), db.getStudents(), db.getTeachers(),
            db.getProjectTeachers(), db.getFormats(), db.getTeacherRoles(), db.getStatuses()
        ]);
        return { users, projects, programs, students, teachers, projectTeachers, formats, teacherRoles, statuses };
    },

    initializeDB
};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { db } from '../services/database';
import { Teacher } from '../types';

interface LoginPageProps {
    onOpenPublicReports: () => void;
}

export const LoginPage: React.FC<LoginPageProps> = ({ onOpenPublicReports }) => {
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [selectedUsername, setSelectedUsername] = useState('');
    const [password, setPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isFetching, setIsFetching] = useState(true);
    const [error, setError] = useState('');
    const { login } = useAuth();

    useEffect(() => {
        const loadTeachers = async () => {
            try {
                const data = await db.getTeachers();
                setTeachers(data);
            } catch (err) {
                console.error("Error al cargar docentes para login:", err);
            } finally {
                setIsFetching(false);
            }
        };
        loadTeachers();
    }, []);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedUsername) {
            setError('Por favor, selecciona tu nombre de la lista.');
            return;
        }
        setError('');
        setIsLoading(true);
        try {
            const success = await login(selectedUsername, password);
            if (!success) {
                setError('Contraseña incorrecta (Cédula).');
            }
        } catch (err) {
            setError('Error de conexión con el servidor.');
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="flex items-center justify-center min-h-screen bg-gray-100 p-4">
            <div className="w-full max-w-md space-y-8 bg-white p-8 rounded-xl shadow-2xl">
                <div className="text-center">
                    <img src="https://i.ibb.co/L8yFz9p/logo.png" alt="Logo" className="h-20 mx-auto mb-4 object-contain"/>
                    <h1 className="text-2xl font-bold text-gray-900 uppercase tracking-tight">Gestor de Proyectos</h1>
                    <p className="mt-2 text-sm text-gray-600">Corporación Universitaria Rafael Núñez</p>
                </div>

                <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Seleccione su Nombre</label>
                            <select
                                required
                                value={selectedUsername}
                                onChange={(e) => setSelectedUsername(e.target.value)}
                                disabled={isFetching}
                                className="block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-primary-500 focus:border-primary-500 sm:text-sm disabled:bg-gray-50"
                            >
                                <option value="">-- Seleccione su nombre --</option>
                                <option value="admin">Administrador del Sistema</option>
                                {teachers.map(t => (
                                    <option key={t.id} value={t.name}>{t.name}</option>
