import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { db, isSupabaseConfigured } from '../services/database';
import { Teacher } from '../types';

interface LoginPageProps {
    onOpenPublicReports: () => void;
}

export const LoginPage: React.FC<LoginPageProps> = ({ onOpenPublicReports }) => {
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [selectedUsername, setSelectedUsername] = useState('');
    const [password, setPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isFetching, setIsFetching] = useState(true);
    const [error, setError] = useState('');
    const [dbConnected, setDbConnected] = useState<boolean | null>(null);
    const { login } = useAuth();

    useEffect(() => {
        const init = async () => {
            if (!isSupabaseConfigured) {
                setError('⚠️ Variables no detectadas. En Vercel, asegúrate de usar los nombres VITE_SUPABASE_URL y VITE_SUPABASE_ANON_KEY. Luego, haz un RE-DEPLOY del proyecto.');
                setIsFetching(false);
                setDbConnected(false);
                return;
            }

            try {
                const connected = await db.checkConnection();
                setDbConnected(connected);
                if (connected) {
                    const data = await db.getTeachers();
                    setTeachers(data);
                } else {
                    setError('❌ Error de Conexión: Las variables existen pero Supabase rechaza la conexión. Verifica que los valores sean correctos.');
                }
            } catch (err) {
                setError('Error crítico al conectar con el servidor.');
                setDbConnected(false);
            } finally {
                setIsFetching(false);
            }
        };
        init();
    }, []);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedUsername) {
            setError('Por favor, selecciona tu nombre de la lista.');
            return;
        }
        setError('');
        setIsLoading(true);
        try {
            const userExists = await db.getUserByUsername(selectedUsername);

            if (!userExists) {
                if (selectedUsername === 'admin') {
                    setError('El usuario administrador no existe. Asegúrate de haber ejecutado el SQL en Supabase.');
                } else {
                    setError('Usuario no encontrado.');
                }
            } else {
                const success = await login(selectedUsername, password);
                if (!success) {
                    setError(selectedUsername === 'admin' 
                        ? 'Clave de administrador incorrecta (Usa la del script SQL).' 
                        : 'Contraseña incorrecta (Usa tu número de cédula).');
                }
            }
        } catch (err) {
            setError('Error durante el inicio de sesión.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="flex items-center justify-center min-h-screen bg-gray-100 p-4">
            <div className="w-full max-w-md space-y-8 bg-white p-8 rounded-xl shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-2">
                    <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${dbConnected ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                        {dbConnected === null ? 'Conectando...' : dbConnected ? 'Conectado a Supabase' : 'Error de Conexión'}
                    </span>
                </div>

                <div className="text-center">
                    <img src="https://i.ibb.co/L8yFz9p/logo.png" alt="Logo" className="h-20 mx-auto mb-4 object-contain" onError={(e) => (e.currentTarget.src = "https://via.placeholder.com/150?text=CURN")}/>
                    <h1 className="text-2xl font-bold text-gray-900 uppercase tracking-tight">Gestor de Proyectos</h1>
                    <p className="mt-2 text-sm text-gray-600">Corporación Universitaria Rafael Núñez</p>
                </div>

                <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Seleccione su Nombre</label>
                            <select
                                required
                                value={selectedUsername}
                                onChange={(e) => setSelectedUsername(e.target.value)}
                                disabled={isFetching || dbConnected === false}
                                className="block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-primary-500 focus:border-primary-500 sm:text-sm disabled:bg-gray-50"
                            >
                                <option value="">-- Seleccione su nombre --</option>
                                <option value="admin">Administrador del Sistema</option>
                                {teachers.map(t => (
                                    <option key={t.id} value={t.name}>{t.name}</option>
                                ))}
                            </select>
                            {isFetching && !error && <p className="text-xs text-gray-500 mt-1 animate-pulse">Cargando docentes...</p>}
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                {selectedUsername === 'admin' ? 'Contraseña Maestra' : 'Contraseña (Cédula)'}
                            </label>
                            <input
                                type="password"
                                required
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                disabled={dbConnected === false && !error.includes('Variables')}
                                className="block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-primary-500 focus:border-primary-500 sm:text-sm disabled:bg-gray-50"
                                placeholder={selectedUsername === 'admin' ? "admin123" : "Tu cédula"}
                            />
                        </div>
                    </div>

                    {error && (
                        <div className="bg-red-50 p-4 rounded-lg border border-red-200">
                            <p className="text-xs text-red-600 font-semibold leading-relaxed">{error}</p>
                            {error.includes('VITE_') && (
                                <div className="mt-2 text-[10px] text-red-500 space-y-1">
                                    <p>1. Ve a Vercel -> Settings -> Environment Variables.</p>
                                    <p>2. Renombra tus variables agregando <strong>VITE_</strong> al inicio.</p>
                                    <p>3. Ve a la pestaña <strong>Deployments</strong>, haz clic en los 3 puntos del último despliegue y selecciona <strong>Redeploy</strong>.</p>
                                </div>
                            )}
                        </div>
                    )}

                    <div className="space-y-3">
                        <button
                            type="submit"
                            disabled={isLoading || isFetching || (dbConnected === false && !error.includes('incorrecta'))}
                            className={`w-full flex justify-center py-2.5 px-4 border border-transparent text-sm font-bold rounded-md text-white shadow-sm transition-all ${isLoading || (dbConnected === false && !error.includes('incorrecta')) ? 'bg-gray-400' : 'bg-primary-600 hover:bg-primary-700'} focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 uppercase`}
                        >
                            {isLoading ? 'Conectando...' : 'Entrar al Gestor'}
                        </button>

                        <div className="relative py-2">
                            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-gray-200"></div></div>
                            <div className="relative flex justify-center text-xs uppercase"><span className="bg-white px-2 text-gray-400">O accede sin cuenta</span></div>
                        </div>

                        <button
                            type="button"
                            onClick={onOpenPublicReports}
                            className="w-full flex justify-center py-2.5 px-4 border border-gray-300 text-sm font-bold rounded-md text-gray-700 bg-white hover:bg-gray-50 transition-all uppercase"
                        >
                            Ver Reportes Públicos
                        </button>
                    </div>
                </form>

                <p className="text-center text-xs text-gray-400">
                    &copy; {new Date().getFullYear()} CURN - Todos los derechos reservados
                </p>
            </div>
        </div>
    );
};

import { createClient } from '@supabase/supabase-js';
import { Project, Student, Teacher, ProjectTeacher, Format, TeacherRole, Status, Program, User } from '../types';

// Intentamos obtener las variables de múltiples fuentes comunes en entornos de desarrollo y producción
const getEnv = (key: string): string => {
    // Fix: Accessing import.meta.env through a type assertion to bypass TypeScript check
    const meta = import.meta as any;
    if (meta && meta.env && meta.env[`VITE_${key}`]) {
        return meta.env[`VITE_${key}`];
    }
    // @ts-ignore - Intentar obtener de process.env (estándar en Node/Polyfills)
    if (typeof process !== 'undefined' && process.env) {
        return process.env[`VITE_${key}`] || process.env[key] || '';
    }
    return '';
};

const supabaseUrl = getEnv('SUPABASE_URL');
const supabaseAnonKey = getEnv('SUPABASE_ANON_KEY');

export const isSupabaseConfigured = !!(supabaseUrl && supabaseAnonKey && supabaseUrl.startsWith('http'));

export const supabase = isSupabaseConfigured 
    ? createClient(supabaseUrl, supabaseAnonKey) 
    : null;

const generateId = (): string => Date.now().toString(36) + Math.random().toString(36).substring(2);

export const initializeDB = () => { 
    if (!isSupabaseConfigured) {
        console.warn('Configuración de Supabase incompleta.');
    }
};

const safeQuery = async (queryPromise: Promise<any>) => {
    if (!supabase) return { data: null, error: new Error('Base de datos no configurada') };
    try {
        const result = await queryPromise;
        if (result.error) throw result.error;
        return result;
    } catch (error: any) {
        console.error("Error en consulta Supabase:", error);
        return { data: null, error };
    }
};

const mapProjectToDB = (p: Partial<Project>) => ({
    id: p.id,
    title: p.title,
    presentation_date: p.presentationDate,
    files_url: p.filesUrl,
    status_id: p.statusId,
    format_id: p.formatId,
    is_approved_by_director: p.isApprovedByDirector,
    written_grade_reviewer1: p.writtenGradeReviewer1,
    presentation_grade_reviewer1: p.presentationGradeReviewer1,
    written_grade_reviewer2: p.writtenGradeReviewer2,
    presentation_grade_reviewer2: p.presentation_grade_reviewer2
});

const mapProjectFromDB = (p: any): Project => ({
    id: p.id,
    title: p.title,
    presentationDate: p.presentation_date,
    filesUrl: p.files_url,
    statusId: p.status_id,
    formatId: p.format_id,
    isApprovedByDirector: p.is_approved_by_director,
    writtenGradeReviewer1: p.written_grade_reviewer1,
    presentationGradeReviewer1: p.presentation_grade_reviewer1,
    writtenGradeReviewer2: p.written_grade_reviewer2,
    presentationGradeReviewer2: p.presentation_grade_reviewer2
});

export const db = {
    checkConnection: async () => {
        if (!supabase) return false;
        try {
            const { error } = await supabase.from('users').select('id').limit(1);
            return !error;
        } catch {
            return false;
        }
    },

    getUsers: async () => {
        const { data } = await safeQuery(supabase?.from('users').select('*') || Promise.resolve({data: []}));
        return (data || []).map(u => ({
            ...u,
            teacherId: u.teacher_id,
            studentId: u.student_id
        }));
    },
    getUserByUsername: async (username: string) => {
        const { data, error } = await safeQuery(supabase?.from('users').select('*').ilike('username', username).single() || Promise.resolve({data: null}));
        if (error || !data) return null;
        return {
            ...data,
            teacherId: data.teacher_id,
            studentId: data.student_id
        };
    },
    deleteUser: async (id: string) => {
        await safeQuery(supabase?.from('users').delete().eq('id', id) || Promise.resolve({}));
    },
    getProjects: async () => {
        const { data } = await safeQuery(supabase?.from('projects').select('*') || Promise.resolve({data: []}));
        return (data || []).map(mapProjectFromDB);
    },
    getProjectById: async (id: string) => {
        const { data } = await safeQuery(supabase?.from('projects').select('*').eq('id', id).single() || Promise.resolve({data: null}));
        return data ? mapProjectFromDB(data) : null;
    },
    addProject: async (project: Omit<Project, 'id'>) => {
        const id = generateId();
        const dbProject = mapProjectToDB({ ...project, id });
        const { data } = await safeQuery(supabase?.from('projects').insert([dbProject]).select().single() || Promise.resolve({data: null}));
        return data ? mapProjectFromDB(data) : null;
    },
    updateProject: async (project: Project) => {
        const dbProject = mapProjectToDB(project);
        const { data } = await safeQuery(supabase?.from('projects').update(dbProject).eq('id', project.id).select().single() || Promise.resolve({data: null}));
        return data ? mapProjectFromDB(data) : null;
    },
    deleteProject: async (id: string) => {
        await safeQuery(supabase?.from('projects').delete().eq('id', id) || Promise.resolve({}));
    },
    getStudents: async () => {
        const { data } = await safeQuery(supabase?.from('students').select('*') || Promise.resolve({data: []}));
        return (data || []).map(s => ({ ...s, projectId: s.project_id, programId: s.program_id }));
    },
    getStudentById: async (id: string) => {
        const { data } = await safeQuery(supabase?.from('students').select('*').eq('id', id).single() || Promise.resolve({data: null}));
        return data ? { ...data, projectId: data.project_id, programId: data.program_id } : null;
    },
    addStudent: async (student: Omit<Student, 'id'>) => {
        const id = generateId();
        const dbStudent = { id, name: student.name, email: student.email, cedula: student.cedula, project_id: student.projectId, program_id: student.programId };
        const { data: newStudent } = await safeQuery(supabase?.from('students').insert([dbStudent]).select().single() || Promise.resolve({data: null}));
        if (newStudent) {
            await safeQuery(supabase?.from('users').insert([{ id: generateId(), username: student.name, password: student.cedula, role: 'student', student_id: id }]) || Promise.resolve({}));
        }
        return newStudent ? { ...newStudent, projectId: newStudent.project_id, programId: newStudent.program_id } : null;
    },
    updateStudent: async (student: Student) => {
        const dbStudent = { name: student.name, email: student.email, cedula: student.cedula, project_id: student.projectId, program_id: student.programId };
        const { data } = await safeQuery(supabase?.from('students').update(dbStudent).eq('id', student.id).select().single() || Promise.resolve({data: null}));
        await safeQuery(supabase?.from('users').update({ username: student.name, password: student.cedula }).eq('student_id', student.id) || Promise.resolve({}));
        return data ? { ...data, projectId: data.project_id, programId: data.program_id } : null;
    },
    deleteStudent: async (id: string) => {
        await safeQuery(supabase?.from('users').delete().eq('student_id', id) || Promise.resolve({}));
        await safeQuery(supabase?.from('students').delete().eq('id', id) || Promise.resolve({}));
    },
    getTeachers: async () => {
        const { data } = await safeQuery(supabase?.from('teachers').select('*') || Promise.resolve({data: []}));
        return data || [];
    },
    getTeacherById: async (id: string) => {
        const { data } = await safeQuery(supabase?.from('teachers').select('*').eq('id', id).single() || Promise.resolve({data: null}));
        return data;
    },
    addTeacher: async (teacher: Omit<Teacher, 'id'>) => {
        const id = generateId();
        const { data: newTeacher } = await safeQuery(supabase?.from('teachers').insert([{ ...teacher, id }]).select().single() || Promise.resolve({data: null}));
        if (newTeacher) {
            await safeQuery(supabase?.from('users').insert([{ id: generateId(), username: teacher.name, password: teacher.cedula, role: 'teacher', teacher_id: id }]) || Promise.resolve({}));
        }
        return newTeacher;
    },
    updateTeacher: async (teacher: Teacher) => {
        const { data } = await safeQuery(supabase?.from('teachers').update(teacher).eq('id', teacher.id).select().single() || Promise.resolve({data: null}));
        await safeQuery(supabase?.from('users').update({ username: teacher.name, password: teacher.cedula }).eq('teacher_id', teacher.id) || Promise.resolve({}));
        return data;
    },
    deleteTeacher: async (id: string) => {
        await safeQuery(supabase?.from('users').delete().eq('teacher_id', id) || Promise.resolve({}));
        await safeQuery(supabase?.from('teachers').delete().eq('id', id) || Promise.resolve({}));
    },
